{
  "name": "Ocean Insight 光纤光谱仪",
  "name_en": "Ocean Insight fiber-optic spectrometer",
  "manufacturer": "Ocean Insight",
  "description": "一种通过 USB 连接的紧凑型光纤光谱仪，用于测量不同波长处的光强分布。实验室中常用于光源与样品的光谱表征，例如透射、反射或发射测量，并可通过调节积分时间适配不同信号强度。",
  "description_en": "A compact USB-connected fiber-optic spectrometer used to measure light intensity as a function of wavelength. In laboratories it is commonly used for spectral characterization of light sources and samples, such as transmission, reflection, or emission measurements, with adjustable integration time for different signal levels.",
  "tag_hints": [
    "fiber optic spectrometer",
    "optical spectroscopy",
    "USB spectrometer",
    "integration time control",
    "wavelength calibration",
    "spectral acquisition",
    "Ocean Insight"
  ],
  "actions": [
    {
      "action_name": "auto-doInitializeDevice",
      "description": "初始化光谱仪并读取校准信息。",
      "description_en": "Initialize the spectrometer and load calibration information."
    },
    {
      "action_name": "auto-doShutdownDevice",
      "description": "关闭光谱仪通信并释放设备连接。",
      "description_en": "Shut down spectrometer communication and release the device connection."
    },
    {
      "action_name": "auto-flushEndpoints",
      "description": "清空光谱仪的 USB 通信缓冲区。",
      "description_en": "Flush the spectrometer's USB communication buffers."
    },
    {
      "action_name": "auto-setIntegrationTime",
      "description": "设置光谱采集积分时间。",
      "description_en": "Set the spectral acquisition integration time."
    },
    {
      "action_name": "auto-getIntegrationTime",
      "description": "获取光谱采集积分时间。",
      "description_en": "Get the spectral acquisition integration time."
    },
    {
      "action_name": "auto-getSerialNumber",
      "description": "获取光谱仪序列号。",
      "description_en": "Get the spectrometer serial number."
    },
    {
      "action_name": "auto-getCalibration",
      "description": "获取光谱仪的波长校准参数。",
      "description_en": "Get the spectrometer wavelength calibration parameters."
    },
    {
      "action_name": "auto-getParameter",
      "description": "获取设备内置参数。",
      "description_en": "Get a built-in device parameter."
    },
    {
      "action_name": "auto-requestSpectrum",
      "description": "请求开始一次光谱采集。",
      "description_en": "Request a spectrum acquisition."
    },
    {
      "action_name": "auto-isSpectrumRequested",
      "description": "查询是否已请求光谱采集。",
      "description_en": "Get whether a spectrum acquisition has been requested."
    },
    {
      "action_name": "auto-isSpectrumReady",
      "description": "查询光谱数据是否已就绪。",
      "description_en": "Get whether the spectrum data is ready."
    },
    {
      "action_name": "auto-getStatus",
      "description": "获取光谱仪状态。",
      "description_en": "Get the spectrometer status."
    },
    {
      "action_name": "auto-getSpectrumData",
      "description": "读取已采集的光谱数据。",
      "description_en": "Retrieve the acquired spectrum data."
    },
    {
      "action_name": "auto-getSpectrum",
      "description": "采集并返回一条完整光谱。",
      "description_en": "Acquire and return a complete spectrum."
    },
    {
      "action_name": "auto-sendCommand",
      "description": "向光谱仪发送底层命令。",
      "description_en": "Send a low-level command to the spectrometer."
    },
    {
      "action_name": "auto-readReply",
      "description": "读取光谱仪返回的底层响应数据。",
      "description_en": "Read low-level reply data returned by the spectrometer."
    }
  ]
}

